  FT["BN-H106"] = {"id":"BN-H106","coverage":"full","language":"en","sourceName":"文莱官方发布渠道","sourceUrl":"","fetchedAt":"2026-10-04","articleCount":7,"structureMode":"ARTICLE","title":{"zh":"S-10-2026-STAMP-ACT-AMENDMENT-ORDER-2026","en":"S-10-2026-STAMP-ACT-AMENDMENT-ORDER-2026 2026","orig":null},"level":"law","status":"active","issuingBody":"文莱官方发布渠道","promulgatedDate":"2026","completenessNote":"全文，共 7 条；取自《东盟法律分类》归档中的 PDF 原件，逐字未改写。","country":"BN","countryName":"文莱","layer":"intl","articles":[{"id":"BN-H106-A1","no":1,"noLabel":{"en":"Article 1"},"text":{"en":"This Order may be cited as the Stamp Act (Amendment) Order, 2026 and shall be deemed to have commenced on 1st January 2013 .\nRepeal of Part 9 of Chapter 34"}},{"id":"BN-H106-A2","no":2,"noLabel":{"en":"Article 2"},"text":{"en":"Part 9 of the Stamp Act, in this Order referred to as the Act, is repealed .\nAmendment of Schedule 1"}},{"id":"BN-H106-A3","no":3,"noLabel":{"en":"Article 3"},"heading":{"en":"Schedule 1 to the Act is amended -"},"text":{"en":"(a) by deleting the items relating to Article 1 from the first and second columns;\n(b) by deleting the items relating to Article 1A from the first and second columns.\nConsequential amendments to other written laws"}},{"id":"BN-H106-A4","no":4,"noLabel":{"en":"Article 4"},"text":{"en":"The provisions of the other written laws specified in the first column of the Schedule are amended in the manner set out in the second column thereof.\n89 12th. MARCH, 2026 APPENDIX B, item no . 41, Delete \"Collector of Estate Duty\" and page 583 substitute with \"Probate Officer\" therefor."}},{"id":"BN-H106-A4-d2","no":4,"noLabel":{"en":"Article 4"},"text":{"en":"Universiti Brunei Darussalam Act (Chapter 157)\nSection 9 Repeal."},"dupIndex":2},{"id":"BN-H106-A5","no":5,"noLabel":{"en":"Article 5"},"text":{"en":"Universiti Islam Sultan Sharif Ali Act (Chapter 212)\nSection 9 Repeal."}},{"id":"BN-H106-A6","no":6,"noLabel":{"en":"Article 6"},"heading":{"en":"Universiti Teknologi Brunei Act (Chapter 214)"},"text":{"en":"Section 26 Repeal.\nMade this 22nd. day of Ramadhan, 1447 Hijriah corresponding to the 12th. day of March, 2026 at Our Istana Nurul !man, Bandar Seri Begawan, Brunei Darussalam.\n91 HIS MAJESTY THE SULTAN AND YANG DI-PERTUAN, BRUNEI DARUSSALAM."}}],"pack":"bn-p06"};
  FT["BN-H107"] = {"id":"BN-H107","coverage":"full","language":"zh","sourceName":"文莱官方发布渠道","sourceUrl":"","fetchedAt":"2026-10-04","articleCount":1,"structureMode":"WHOLE","title":{"zh":"自由贸易区条例","en":null,"orig":null},"level":"law","status":"active","docNumber":"年份不详","issuingBody":"文莱官方发布渠道","completenessNote":"文本未能可靠切分为条文（或原件为目录式排版），按整篇收录，未作改写。","country":"BN","countryName":"文莱","layer":"intl","articles":[{"id":"BN-H107-A1","no":1,"noLabel":{"zh":"第 1 条"},"text":{"zh":"文莱 2014 年自由贸易区法令文莱 2014 年自由贸易区条例目录第 1 条 引称与实施日期第 2 条 自由贸易区内安保第 3 条 办公室和检查站第 4 条 不得建造违法建筑物或构筑物第 5 条 不得转让应税货物第 6 条 保存准确记录第 7 条 指示文莱 2014 年自由贸易区法令文莱 2014 年自由贸易区条例第 1 条 引称与实施日期本条例可引称为《自由贸易区条例（2014 年）》，与《自由贸易区法令 （2014 年）》同日施行。\n第 2 条 自由贸易区内安保自由贸易区管理机构应—— （a）安排沿自由区边界修建围栏或围墙并加以维护，同时修建合适的大门；\n（b）在管理机构认为必要的时间内保持围栏或围墙及大门的照明；\n（c）遵守部长所作之其他指示，以防止未经授权的人员或货物进出自由区。\n第 3 条 办公室和检查站自由贸易区管理机构应为区内海关检查站办公场所之设置提供设施。\n第 4 条 不得建造违法建筑物或构筑物除经海关署长书面许可外，不得在距自由贸易区边界 6 米以内之区域建造任何建筑物或构筑物。\n第 5 条 不得转让应税货物\n（1）除经海关官员的事先书面许可外，任何人不得将某一自由贸易区内应税货物转移至另一自由贸易区。\n（2）凡欲获得上述书面许可者，须按管理机构规定之形式和方式提交声明。\n（3）依本条例之规定授予许可时，海关官员可施加其认为合适之条件。\n第 6 条 保存准确记录\n（1）凡经管理机构依第 9 条之规定准许在自由贸易区内进行组装、混合或管理货物者，须保存包括管理机构所要求的详情在内的关于许可作业的完整准确纪录。\n（2）上述记录应按海关高级官员的要求予以制作以供检查。\n第 7 条 指示\n（1）凡未经该区管理机构之许可者，不得进出自由贸易区。\n（2）凡获得许可者均应遵守管理机构所作指示。\n本条例制定于回历 1436 年元旦 2 月 28 日，即公历 2014 年 12 月 21 日。"}}],"pack":"bn-p06"};
  FT["BN-H109"] = {"id":"BN-H109","coverage":"full","language":"zh","sourceName":"文莱官方发布渠道","sourceUrl":"","fetchedAt":"2026-10-04","articleCount":1,"structureMode":"WHOLE","title":{"zh":"2013年先锋产业和先锋产品法","en":null,"orig":null},"level":"law","status":"active","issuingBody":"文莱官方发布渠道","promulgatedDate":"2013","completenessNote":"文本未能可靠切分为条文（或原件为目录式排版），按整篇收录，未作改写。","country":"BN","countryName":"文莱","layer":"intl","articles":[{"id":"BN-H109-A1","no":1,"noLabel":{"zh":"第 1 条"},"text":{"zh":"文莱 2001 年投资激励法令 (S 48/2001) 2013年先锋产业和先锋产品法令目录第 1 条 引称第 2 条 宣布为先锋产业和先锋产品文莱 2001 年投资激励法令 (S 48/2001) 2013年先锋产业和先锋产品法令在行使《2001 年投资激励法》第 4 条第（1）款所赋予的权力时，工业和第一资源部作出以下命令—— 第 1 条 引称本法可引用为《2013 年先锋产业和先锋产品法令》。\n第 2 条 宣布为先锋产业和先锋产品本法附表第一栏所列产业及其第二栏所列产品分别被为先锋产业和先锋产品法令。\n附表产业 产品制备动物饲料宠物饲料；\n牲畜饲料，包括动物浓缩饲料和饲料添加剂以及未混合（单一） 饲料的制备；\n处理屠宰废物产生的动物饲料。\n本法令制定于回历 1434 年 11 月 12 日，即公历 2013 年 2 月 19 日。"}}],"pack":"bn-p06"};
